    const adjustments=await window.LTSupabase.from('customer_invoice_credit_adjustments',ctx.accessToken).select('*',filter+'&original_invoice_id=eq.'+encodeURIComponent(invoiceId));
    const refunds=await window.LTSupabase.from('customer_credit_refunds',ctx.accessToken).select('*',filter+'&original_invoice_id=eq.'+encodeURIComponent(invoiceId));
    const credited=(adjustments||[]).reduce((s,r)=>s+Number(r.credit_amount_ore||0),0),refundDue=(adjustments||[]).reduce((s,r)=>s+Number(r.refund_due_ore||0),0),refundPaid=(refunds||[]).reduce((s,r)=>s+Number(r.amount_ore||0),0);
