      p_company_id:ctx.company.id,p_request_id:issueRequestId,p_payload_sha256:payloadSha256,p_customer_number:value.customerNumber,
      p_invoice_date:document.invoiceDate,p_posting_date:document.postingDate,p_due_date:document.dueDate,p_total_ore:document.totalOre,p_vat_ore:document.vatOre,
      p_payment_account:document.seller.bankgiro,p_document_json:document,p_document_sha256:documentSha256,p_pdf_sha256:pdfSha256,
      p_object_path:objectPath,p_file_name:fileName,p_size_bytes:pdfArray.byteLength,p_journal_lines:journalLines
