function accountOptions(vatRate,value=''){const raw=String(vatRate??'').trim(),list=raw?Invoice.accountsForVat(accounts(),Number(raw)):[];return '<option value="">Välj intäktskonto</option>'+list.map(a=>`<option value="${esc(a.number)}" ${a.number===value?'selected':''}>${esc(a.number)} · ${esc(a.name)}</option>`).join('');}
