function blankLine(){return {description:'',quantity:'1',unit:'',unitPrice:'0,00',vatRate:'',revenueAccount:''};}
function normalizedDraftVatRate(row,invoiceDate){const raw=String(row?.vatRate??'').trim();if(['25','12','6'].includes(raw))return raw;if(row?.vatTreatment){try{const legacy=String(Invoice.vatTreatmentRate(row.vatTreatment,invoiceDate));if(['25','12','6'].includes(legacy))return legacy;}catch{}}return '';}
function normalizeDraft(value){value.seller=sellerFromCompany();value.buyer=buyerFromCustomer(value.customerNumber);value.invoiceDate=value.invoiceDate||today();value.postingDate=value.postingDate||today();value.paymentTermsDays=Number(value.paymentTermsDays??30);value.dueDate=value.dueDate||plusDays(value.invoiceDate,value.paymentTermsDays);value.ourReference=value.ourReference||'';value.yourReference=value.yourReference||'';value.notes=value.notes||'';value.useFees=Boolean(value.useFees);value.includeMessage=Boolean(value.includeMessage&&value.notes);value.lines=(value.lines?.length?value.lines:[blankLine()]).map(row=>({description:row.description||'',quantity:String(row.quantity??'1'),unit:row.unit||'',unitPrice:String(row.unitPrice??'0,00'),vatRate:normalizedDraftVatRate(row,value.invoiceDate),revenueAccount:row.revenueAccount||''}));value.administration={amount:value.administration?.amount||'0,00',vatRate:'25',revenueAccount:'3690'};value.freight={amount:value.freight?.amount||'0,00',vatRate:'25',revenueAccount:'3520'};return value;}
function freshDraft(){const saved=isDemo?Demo.state().invoiceDraft:privateDraftRecord?.draft;if(!isDemo)issueRequestId=privateDraftRecord?.requestId||crypto.randomUUID();if(saved)return normalizeDraft(copy(saved));return normalizeDraft({customerNumber:'',buyer:{name:'',address:'',orgNumber:'',email:''},seller:sellerFromCompany(),invoiceDate:today(),postingDate:today(),dueDate:plusDays(today(),30),paymentTermsDays:30,currency:'SEK',ourReference:'',yourReference:'',notes:'',useFees:false,includeMessage:false,lines:[blankLine()],freight:{amount:'0,00'},administration:{amount:'0,00'}});}
function chooseCustomer(number){const c=customerForNumber(number);draft.customerNumber=number;syncDraftBuyer();if(!c)return;draft.paymentTermsDays=Number(c.paymentTermsDays??30);draft.dueDate=plusDays(draft.invoiceDate,draft.paymentTermsDays);}
function get(name){return name.split('.').reduce((value,key)=>value?.[key],draft);}
function set(name,value){const parts=name.split('.');if(parts.length===1)draft[name]=value;else draft[parts[0]][parts[1]]=value;}
function field(label,name,options={}){const v=get(name)??'',required=options.required?'required':'',wide=options.wide?'wide':'';if(options.textarea)return `<label class="${wide}">${esc(label)}${options.required?' *':''}<textarea name="${name}" rows="${options.rows||3}" maxlength="${options.max||600}" ${required}>${esc(v)}</textarea></label>`;return `<label class="${wide}">${esc(label)}${options.required?' *':''}<input name="${name}" type="${options.type||'text'}" value="${esc(v)}" maxlength="${options.max||120}" ${required} ${options.type==='number'?'min="0" max="365" step="1"':''}></label>`;}
function readonlyField(label,value,wide=false,textarea=false){return `<label class="${wide?'wide':''}">${esc(label)}${textarea?`<textarea rows="3" readonly aria-readonly="true">${esc(value||'')}</textarea>`:`<input value="${esc(value||'')}" readonly aria-readonly="true">`}</label>`;}
function section(title,body,open=true){return `<details class="invoice-section" ${open?'open':''}><summary>${title}</summary><div class="invoice-section-body">${body}</div></details>`;}
function vatOptions(value){return '<option value="">Välj momssats</option>'+[25,12,6].map(v=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${v} %</option>`).join('');}
function lineHtml(row,index){const required=(label,key)=>`<label>${label}<input data-row-field="${key}" value="${esc(row[key])}" ${['quantity','unitPrice'].includes(key)?'inputmode="decimal"':''} required maxlength="120"></label>`;return `<div class="invoice-line-editor" data-row="${index}"><div class="invoice-line-head"><h3>Fakturarad ${index+1}</h3><button class="button ghost small" type="button" data-remove-row="${index}" ${draft.lines.length===1?'disabled':''}>Ta bort rad</button></div><div class="invoice-grid invoice-line-fields"><label class="description-field">Benämning *<textarea data-row-field="description" maxlength="1200" rows="2" required>${esc(row.description)}</textarea></label>${required('Antal *','quantity')}<label>Enhet<input data-row-field="unit" value="${esc(row.unit)}" maxlength="30"></label>${required('À-pris exkl. moms, SEK *','unitPrice')}<label>Momssats *<select data-row-field="vatRate" required>${vatOptions(row.vatRate)}</select><small>Styr vilka intäktskonton som kan väljas</small></label><label class="account-field">Intäktskonto *<select data-revenue-select data-row-field="revenueAccount" required>${accountOptions(row.vatRate,row.revenueAccount)}</select></label></div></div>`;}
function editor(){const list=customers();const customerRegisterLink=draft.customerNumber?`<p class="invoice-help"><strong>Kunduppgifterna hämtas från kundregistret och kan inte ändras på fakturan.</strong> <button class="button ghost small" type="button" data-action="edit-customer-register">Ändra ${esc(draft.customerNumber)} i kundregistret</button></p>`:'<p class="invoice-help">Välj en kund. Namn, organisationsnummer, adress och e-post hämtas automatiskt från kundregistret.</p>';const fees=draft.useFees?`<div class="invoice-grid"><label>Fakturaavgift exkl. moms (SEK)<input name="administration.amount" inputmode="decimal" value="${esc(draft.administration.amount)}"></label>${readonlyField('Moms för fakturaavgift','25 %')}${readonlyField('Intäktskonto för fakturaavgift','3690 · Övriga sidointäkter',true)}<label>Frakt, kr exkl. moms (SEK)<input name="freight.amount" inputmode="decimal" value="${esc(draft.freight.amount)}"></label>${readonlyField('Moms för frakt','25 %')}${readonlyField('Intäktskonto för frakt','3520 · Fakturerade frakter',true)}</div>`:'<p class="invoice-help">Aktivera valet ovan om fakturaavgift eller frakt ska tas med.</p>';const message=draft.includeMessage?field('Meddelande på faktura','notes',{textarea:true,wide:true,max:3000}):'<p class="invoice-help">Aktivera valet ovan om ett meddelande ska visas på kundens faktura.</p>';return `<div class="invoice-toolbar"><div><span class="eyebrow">Fakturautställning</span><h2>Ny kundfaktura</h2><p>Endast uppgifter som behövs för kundfakturan och bokföringen visas. Stjärna markerar obligatoriska uppgifter.</p></div><button class="button ghost" data-action="list">Till fakturalistan</button></div><form id="invoice-form">${section('1. Mottagare & kund',`<div class="invoice-grid"><label class="wide">Kundnummer *<select name="customerNumber" required><option value="">Välj kund</option>${list.map(c=>`<option value="${esc(c.customerNumber)}" ${c.customerNumber===draft.customerNumber?'selected':''}>${esc(c.customerNumber)} · ${esc(c.name)}</option>`).join('')}</select></label>${readonlyField('Företagsnamn - kund',draft.buyer.name)}${readonlyField('Organisationsnummer - kund',draft.buyer.orgNumber)}${readonlyField('Fakturaadress, postnummer och ort - kund',draft.buyer.address,true,true)}${readonlyField('Mottagarens e-post - kund',draft.buyer.email)}</div>${customerRegisterLink}`)}${section('2. Datum, referens och leverans',`<div class="invoice-grid">${field('Fakturadatum','invoiceDate',{required:true,type:'date'})}${field('Förfallodatum','dueDate',{required:true,type:'date'})}${field('Betalningsvillkor dagar','paymentTermsDays',{type:'number',required:true})}${field('Vår referens','ourReference')}${field('Er referens','yourReference')}<label class="wide">OCR / betalningsreferens<input value="Fakturanummer tilldelas vid bokföring" readonly aria-readonly="true"></label></div><p class="invoice-help">Fakturadatum fylls i automatiskt och kan ändras. Förfallodatum räknas om från fakturadatum + betalningsvillkor. Bokföringsdatum hanteras internt och visas inte som ett kundfakturafält. OCR låses alltid till fakturanumret.</p>`)}${section('3. Fakturarader och valfri intäktskontering',`<p class="invoice-help"><strong>Välj momssats först: 25 %, 12 % eller 6 %.</strong> Intäktskontona filtreras därefter automatiskt. Ett konto med fel momskoppling kan varken väljas här eller bokföras i motorn. <a href="${url('./accounts.html')}" target="_blank" rel="noopener">Öppna kontoplan / lägg till eget intäktskonto</a>.</p>${draft.lines.map(lineHtml).join('')}<button class="button ghost" type="button" data-action="add-row">+ Lägg till fakturarad</button>`)}${section('4. Avgifter och öresutjämning',`<label class="wide checkbox-label"><input name="useFees" type="checkbox" ${draft.useFees?'checked':''}> Använd fakturaavgift och/eller frakt</label>${fees}<p class="invoice-help">Öresutjämning beräknas alltid automatiskt och visas separat på fakturan.</p>`)}${section('5. Avsändare, kontakt och betalningsuppgifter',`<div class="invoice-grid">${readonlyField('Avsändarens juridiska namn',draft.seller.name)}${readonlyField('Organisationsnummer',draft.seller.orgNumber)}${readonlyField('Adress, postnummer och ort',draft.seller.address,true)}${readonlyField('VAT-nummer / momsregistreringsnummer',draft.seller.vatNumber)}${readonlyField('Telefon',draft.seller.phone)}${readonlyField('E-post',draft.seller.email)}${readonlyField('Webbplats',draft.seller.website)}${readonlyField('Skattestatus',draft.seller.taxStatus)}${readonlyField('Bankgiro',draft.seller.bankgiro,true)}</div><p class="invoice-help">Uppgifterna hämtas centralt från företagsinformationen och ändras inte i fakturafönstret.</p>`,false)}${section('6. Meddelanden',`<label class="wide checkbox-label"><input name="includeMessage" type="checkbox" ${draft.includeMessage?'checked':''}> Lägg till meddelande på faktura</label>${message}`)}<div class="invoice-panel-footer"><div class="invoice-actions"><button class="button ghost" type="button" data-action="save-draft">Spara utkast</button><button class="button ghost" type="button" data-action="open-draft-pdf">Öppna faktura PDF</button><button class="button ghost" type="button" data-action="print-draft-pdf">Skriv ut faktura PDF</button><button class="button" type="submit" ${!isDemo&&!issueReady?'disabled':''}>Skapa och bokför faktura</button></div><span class="invoice-muted">Inget skickas till kund eller bank.</span></div></form>`;}
function readForm(){const form=document.getElementById('invoice-form');if(!form)return;for(const [name,value] of new FormData(form).entries())if(!['useFees','includeMessage'].includes(name))set(name,value);draft.useFees=Boolean(form.elements.useFees?.checked);draft.includeMessage=Boolean(form.elements.includeMessage?.checked);if(!draft.includeMessage)draft.notes='';draft.lines=[...form.querySelectorAll('[data-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-row-field]')].map(input=>[input.dataset.rowField,input.value])));draft.seller=sellerFromCompany();syncDraftBuyer();draft.administration.vatRate='25';draft.administration.revenueAccount='3690';draft.freight.vatRate='25';draft.freight.revenueAccount='3520';}
function input(){const value=copy(draft);value.seller=sellerFromCompany();value.paymentTermsDays=Number(value.paymentTermsDays);value.lines=value.lines.map(r=>({...r}));if(value.useFees){const feeOre=Money.parseOre(value.administration.amount||'0',{allowNegative:false,label:'Fakturaavgift'});if(feeOre)value.lines.push({kind:'administration',description:'Fakturaavgift',quantity:'1',unit:'st',unitPrice:value.administration.amount,vatTreatment:'se-standard-25',vatRate:'25',revenueAccount:'3690'});const freightOre=Money.parseOre(value.freight.amount||'0',{allowNegative:false,label:'Frakt'});if(freightOre)value.lines.push({kind:'freight',description:'Frakt',quantity:'1',unit:'st',unitPrice:value.freight.amount,vatTreatment:'se-standard-25',vatRate:'25',revenueAccount:'3520'});}value.notes=value.includeMessage?value.notes:'';return value;}
function invoiceRecords(){return isDemo?(Demo.section('customerInvoices')||[]):privateInvoices}
function invoiceMatches(record,query){const q=String(query||'').trim().toLocaleLowerCase('sv-SE');if(!q)return true;return [record.invoiceNumber,record.ocr,record.customerName,record.customerNumber].some(value=>String(value||'').toLocaleLowerCase('sv-SE').includes(q))}
function filteredInvoices(){return invoiceRecords().filter(record=>invoiceMatches(record,search))}
function invoiceRows(){return filteredInvoices().slice().reverse().map(r=>`<tr><td><b>${esc(r.invoiceNumber)}</b><br>${esc(r.ocr)}</td><td>${esc(r.customerName)}<br><small>${esc(r.customerNumber)}</small></td><td>${Number(r.totalOre||0)<0?'Kreditfaktura':'Faktura'}</td><td>${esc(r.invoiceDate)}</td><td>${esc(r.dueDate)}</td><td class="money">${amount(r.totalOre)}</td><td><button class="button ghost small" data-preview="${esc(r.id)}">Visa / skriv ut</button></td></tr>`).join('')||'<tr><td colspan="7">Inga fakturor matchar sökningen.</td></tr>'}
function invoiceSearchSuggestions(){return search?filteredInvoices().slice(0,8):[]}
function invoiceSearchResults(){const rows=invoiceSearchSuggestions();if(!rows.length)return '<div class="shared-search-empty">Inga kundfakturor matchar sökningen.</div>';return rows.map((r,index)=>`<button type="button" class="shared-search-option ${index===invoiceSearchActiveIndex?'active':''}" role="option" aria-selected="${index===invoiceSearchActiveIndex?'true':'false'}" data-preview="${esc(r.id)}" data-invoice-search-option><span><b>${Number(r.totalOre||0)<0?'Kreditfaktura':'Faktura'} ${esc(r.invoiceNumber)}</b><small>${esc(r.customerName)} · ${esc(r.customerNumber)}</small></span><strong>${amount(r.totalOre)}</strong></button>`).join('')}
function updateInvoiceSearchUi(){const field=app.querySelector('.invoice-search'),results=document.getElementById('invoice-search-results'),body=app.querySelector('.sales-table tbody');if(body)body.innerHTML=invoiceRows();if(!field||!results)return;const open=Boolean(invoiceSearchOpen&&search);field.setAttribute('aria-expanded',open?'true':'false');results.hidden=!open;if(open)results.innerHTML=invoiceSearchResults()}
function closeInvoiceSearch(){invoiceSearchOpen=false;invoiceSearchActiveIndex=-1;const field=app.querySelector('.invoice-search'),results=document.getElementById('invoice-search-results');field?.setAttribute('aria-expanded','false');if(results)results.hidden=true}
function listHtml(){return `<div class="invoice-toolbar"><div><span class="eyebrow">Försäljning</span><h2>Kundfakturor</h2><p>Skapa, granska, skriv ut och kreditera fakturadokument. Saldo, inbetalningar och avprickning hanteras i Kundreskontra.</p></div><button class="button" data-action="new">+ Ny kundfaktura</button></div><div class="shared-search-shell invoice-search-shell"><input class="invoice-search" type="search" role="combobox" aria-autocomplete="list" aria-controls="invoice-search-results" aria-expanded="${invoiceSearchOpen&&search?'true':'false'}" aria-label="Sök fakturor" autocomplete="off" placeholder="Sök fakturanummer, OCR, kund eller kundnummer" value="${esc(search)}"><div id="invoice-search-results" class="shared-search-results" role="listbox" ${invoiceSearchOpen&&search?'':'hidden'}>${invoiceSearchOpen&&search?invoiceSearchResults():''}</div></div><div class="sales-panel"><div class="table-scroll"><table class="sales-table"><thead><tr><th>Faktura / OCR</th><th>Kund</th><th>Typ</th><th>Fakturadatum</th><th>Förfallodatum</th><th>Belopp</th><th>Åtgärd</th></tr></thead><tbody>${invoiceRows()}</tbody></table></div></div>`;}
function previewHtml(){
  const d=preview,isCredit=d.documentType==='KREDITFAKTURA',creditable=Number(previewCreditSummary?.creditableOre||0);
  const canCredit=!isDemo&&previewRecord&&Number(previewRecord.totalOre||0)>0&&creditable>0;
  const creditInfo=!isCredit&&previewCreditSummary?.creditedOre>0
    ?`<div class="invoice-alert"><b>Delvis krediterad.</b> Krediterat ${amount(previewCreditSummary.creditedOre)} av ${amount(previewRecord.totalOre)}. Kvar att kunna kreditera: ${amount(creditable)}.</div>`
    :isCredit&&previewCredit?.refundStatus==='pending'
      ?`<div class="invoice-alert"><b>Återbetalning väntar.</b> ${amount(previewCredit.refundOutstandingOre)} ska återbetalas till kunden. Själva bankhändelsen och avprickningen hanteras i Kundreskontra.</div>`
      :isCredit&&previewCredit?.refundStatus==='refunded'
        ?`<div class="demo-banner"><b>Återbetalningen är registrerad.</b> ${amount(previewCredit.refundPaidOre)} bokfördes från konto ${esc(previewCredit.refund?.refundAccount||'')} den ${esc(previewCredit.refund?.refundDate||'')}.</div>`:'';
  return `<div class="invoice-toolbar"><div><span class="eyebrow">Granskning & utskrift</span><h2>${isCredit?'Kreditfaktura':'Faktura'} ${esc(d.invoiceNumber)}</h2><p>OCR är låst till fakturanumret. Bokföringsdatum visas endast internt och inte på kundens PDF.</p></div><button class="button ghost" data-action="${previewRecord?'list':'edit'}">${previewRecord?'Till fakturalistan':'Tillbaka till utkast'}</button></div>${creditInfo}${d.warnings?.length?`<div class="invoice-alert">${d.warnings.map(esc).join('<br>')}</div>`:''}<div class="invoice-preview-card"><h3>${esc(d.buyer.name)}</h3><div class="invoice-preview-meta"><p><b>Avsändare</b><br>${esc(d.seller.name)}<br>${esc(d.seller.address)}<br>Org.nr: ${esc(d.seller.orgNumber)}<br>VAT: ${esc(d.seller.vatNumber)}</p><p><b>Mottagare</b><br>${esc(d.buyer.name)}<br>${esc(d.buyer.address||'Adress saknas i äldre underlag')}<br>Fakturadatum: ${esc(d.invoiceDate)}<br>Förfallodatum: ${esc(d.dueDate)}<br>OCR: ${esc(d.ocr)}</p></div><div class="table-scroll"><table class="sales-table"><thead><tr><th>Benämning</th><th>Antal</th><th>Enhet</th><th>À-pris</th><th>Moms</th><th>Intäktskonto (internt)</th><th>Netto</th></tr></thead><tbody>${d.lines.map(r=>`<tr><td>${esc(r.description)}</td><td>${Money.formatQuantity(r.quantityMilli)}</td><td>${esc(r.unit)}</td><td class="money">${amount(r.unitPriceOre)}</td><td>${r.vatRate==null?'Ej specificerad':esc(r.vatRate)+' %'}</td><td><b>${esc(r.revenueAccount||'Saknas i äldre underlag')}</b><br><small>${esc(r.revenueAccountName||'')}</small></td><td class="money">${amount(r.netOre)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-totals"><div><span>Belopp före moms</span><strong>${amount(d.netOre)}</strong></div><div><span>Total moms</span><strong>${amount(d.vatOre)}</strong></div><div><span>Öresutjämning</span><strong>${amount(d.roundingOre)}</strong></div><div><span>${isCredit?'Kreditbelopp':'Att betala'}</span><strong>${amount(d.totalOre)}</strong></div></div></div><div class="invoice-panel-footer"><div class="invoice-actions"><button class="button" data-action="open-pdf">Öppna faktura PDF</button><button class="button ghost" data-action="print-pdf">Skriv ut faktura PDF</button>${canCredit?'<button class="button ghost" data-action="credit-invoice">Kreditera faktura</button>':''}${isCredit&&previewCredit?.refundStatus==='pending'?`<a class="button" href="./index.html?invoice=${encodeURIComponent(previewRecord.id)}">Hantera återbetalning i Kundreskontra</a>`:''}</div></div>`;
}
function creditInvoiceModal(){if(!creditDialog)return'';const maxOre=Number(creditDialog.maxOre||0),currentText=String(creditDialog.amountText||inputAmount(maxOre));let parsedOre=0;try{parsedOre=Money.parseOre(currentText,{allowNegative:false,label:'Kreditbelopp'})}catch{}const openOre=Math.max(0,Number(previewRecord?.remainingOre||0)),offsetOre=Math.min(parsedOre,openOre),refundOre=Math.max(0,parsedOre-openOre);return `<div class="modal-backdrop" data-credit-cancel><section class="modal" role="dialog" aria-modal="true" aria-labelledby="credit-dialog-title" data-stop><header class="modal-head"><div><span class="eyebrow">Kreditfaktura</span><h3 id="credit-dialog-title">Kreditera faktura ${esc(previewRecord?.invoiceNumber||'')}</h3></div><button type="button" class="button ghost small" data-credit-cancel aria-label="Stäng">×</button></header><div class="modal-body"><p>Du kan kreditera hela eller delar av fakturan. Beloppet fördelas proportionellt över originalets rader och moms.</p><form id="credit-invoice-form"><label class="field">Belopp inklusive moms<input name="creditAmount" inputmode="decimal" value="${esc(currentText)}" required></label><small>Högsta tillgängliga kreditbelopp: ${amount(maxOre)}</small><label class="field">Orsak<textarea name="reason" minlength="5" maxlength="500" rows="3" required>${esc(creditDialog.reason||'Felaktig faktura')}</textarea></label><div class="reminder-summary"><span>Kvittas mot öppet saldo</span><strong>${amount(offsetOre)}</strong><span>Eventuell återbetalning</span><strong>${amount(refundOre)}</strong></div><p class="form-error">${esc(creditDialog.error||'')}</p><div class="modal-actions"><button type="button" class="button ghost" data-credit-cancel>Avbryt</button><button type="submit" class="button">Skapa kreditfaktura</button></div></form></div></section></div>`;}
function render(){const banner=isDemo?'<div class="demo-banner"><b>Demo med fiktiva uppgifter.</b> Fakturor sparas i denna webbläsare. Inga riktiga utskick eller betalningar sker.</div>':issueReady?'<div class="demo-banner"><b>Skyddad fakturering.</b> Bokföring sker i företagets privata databas. Inget skickas automatiskt till kunden.</div>':`<div class="invoice-alert"><b>Bokföring spärrad.</b> ${esc(issueBlocker||'Företagets fakturauppgifter måste verifieras före bokföring.')}</div>`;app.innerHTML=`<div class="portal"><aside class="sidebar"></aside><section class="main"><header class="topbar"><div><h1>Kundfakturor</h1><p>Ekonomi / Fakturautställning</p></div><span class="user-chip">${esc(isDemo?'Demoföretag':(company.displayName||company.legalName||'Skyddad företagsmiljö'))}</span></header><main class="content invoice-workspace">${banner}<div id="invoice-alert" class="invoice-alert" role="alert" tabindex="-1" hidden></div>${view==='edit'?editor():view==='preview'?previewHtml():listHtml()}</main></section></div>${creditInvoiceModal()}`;if(busy)for(const b of app.querySelectorAll('button'))b.disabled=true;if(view==='list')updateInvoiceSearchUi();}
function notify(message){const box=document.getElementById('invoice-alert');if(box){box.textContent=message;box.hidden=false;box.focus();}}function restoreButtonStates(){for(const button of app.querySelectorAll('button')){const singleLineRemove=button.hasAttribute('data-remove-row')&&draft?.lines.length===1;const blockedInvoiceSubmit=button.type==='submit'&&button.closest('#invoice-form')&&!isDemo&&!issueReady;button.disabled=Boolean(singleLineRemove||blockedInvoiceSubmit);}}
async function outputPdf(doc=preview,{archived=true}={}){if(isSupabase&&archived&&previewRecord?.id){const ctx=await supabaseContext(),rows=await window.LTSupabase.from('customer_invoice_documents',ctx.accessToken).select('*','company_id=eq.'+encodeURIComponent(ctx.company.id)+'&invoice_id=eq.'+encodeURIComponent(previewRecord.id));const row=rows?.[0];if(!row)throw new Error('Den arkiverade PDF-fakturan saknas i Supabase.');const blob=await window.LTSupabase.storage.download('lt-documents',row.object_path,ctx.accessToken);return new Uint8Array(await blob.arrayBuffer());}if(!isDemo&&!isSupabase&&archived&&previewRecord?.id){const response=await fetch(`/api/v1/customer-invoices/${encodeURIComponent(previewRecord.id)}/pdf`,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'Den arkiverade PDF-fakturan kunde inte hämtas.');}return new Uint8Array(await response.arrayBuffer());}return Pdf.createInvoicePdf(doc,{record:previewRecord||{}});}
async function openPdf(doc=preview,print=false,options={}){const tab=window.open('about:blank','_blank');if(!tab)throw new Error('Webbläsaren blockerade PDF-fönstret. Tillåt popup-fönster och försök igen.');tab.opener=null;try{const bytes=await outputPdf(doc,options),blob=new Blob([bytes],{type:'application/pdf'}),href=URL.createObjectURL(blob);tab.location.href=href;if(print)setTimeout(()=>{try{tab.focus();tab.print();}catch{}},1200);setTimeout(()=>URL.revokeObjectURL(href),120000);}catch(error){tab.close();throw error;}}
async function draftDocument(){readForm();const doc=Invoice.prepare(input(),{accounts:accounts(),requireVatTreatment:false,requireSellerBankgiro:false});await Pdf.createInvoicePdf(doc);return doc;}
function refreshAccounts(){if(view!=='edit')return;for(const select of app.querySelectorAll('[data-revenue-select]')){const row=select.closest('[data-row]');if(!row)continue;const vat=row.querySelector('[data-row-field="vatRate"]')?.value||'',value=select.value,html=accountOptions(vat,value);if(select.innerHTML!==html)select.innerHTML=html;if(![...select.options].some(o=>o.value===value))select.value='';}}
document.addEventListener('input',event=>{if(event.target.closest('#credit-invoice-form')&&creditDialog){const form=event.target.closest('#credit-invoice-form'),fd=new FormData(form);creditDialog={...creditDialog,amountText:String(fd.get('creditAmount')||''),reason:String(fd.get('reason')||''),error:''};}if(event.target.closest('#invoice-form'))dirty=true;if(event.target.matches('.invoice-search')){search=event.target.value;invoiceSearchOpen=Boolean(search.trim());invoiceSearchActiveIndex=-1;updateInvoiceSearchUi();}});
document.addEventListener('focusin',event=>{if(event.target.matches('.invoice-search')&&search.trim()){invoiceSearchOpen=true;updateInvoiceSearchUi()}});
document.addEventListener('keydown',event=>{if(!event.target.matches('.invoice-search'))return;const rows=invoiceSearchSuggestions();if(event.key==='Escape'){closeInvoiceSearch();return}if(!rows.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();invoiceSearchOpen=true;const step=event.key==='ArrowDown'?1:-1;invoiceSearchActiveIndex=(invoiceSearchActiveIndex+step+rows.length)%rows.length;updateInvoiceSearchUi();return}if(event.key==='Enter'&&invoiceSearchOpen){event.preventDefault();const options=[...app.querySelectorAll('[data-invoice-search-option]')],option=options[Math.max(0,invoiceSearchActiveIndex)];option?.click();}});
document.addEventListener('click',event=>{if(view==='list'&&invoiceSearchOpen&&!event.target.closest('.invoice-search-shell')&&!event.target.closest('[data-invoice-search-option]'))closeInvoiceSearch();});
document.addEventListener('change',event=>{if(!event.target.closest('#invoice-form'))return;readForm();dirty=true;if(event.target.name==='customerNumber'){chooseCustomer(event.target.value);later(render);return;}if(['paymentTermsDays','invoiceDate'].includes(event.target.name)){if(event.target.name==='invoiceDate')draft.postingDate=draft.invoiceDate;try{draft.dueDate=plusDays(draft.invoiceDate,draft.paymentTermsDays);}catch{}later(render);return;}if(event.target.dataset.rowField==='vatRate'){const rowElement=event.target.closest('[data-row]'),rowIndex=Number(rowElement?.dataset.row),rate=event.target.value;draft.lines[rowIndex].vatRate=rate;draft.lines[rowIndex].revenueAccount='';const accountSelect=rowElement?.querySelector('[data-row-field="revenueAccount"]');if(accountSelect){accountSelect.innerHTML=accountOptions(rate,'');accountSelect.value='';}return;}if(['useFees','includeMessage'].includes(event.target.name))later(render);});
document.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target||busy)return;const action=target.dataset.action;try{if(target.dataset.preview){if(isDemo){previewRecord=(Demo.section('customerInvoices')||[]).find(i=>i.id===target.dataset.preview);preview=Invoice.documentFor(previewRecord,company);previewCredit=null;previewCreditSummary=null;}else if(isSupabase){await loadSupabaseInvoiceDetail(target.dataset.preview);}else{const detail=await api('/customer-invoices/'+encodeURIComponent(target.dataset.preview));if(!detail.document)throw new Error('Fullständigt fakturaunderlag saknas för den här äldre fakturan.');previewRecord=detail.invoice;preview=detail.document;previewCredit=detail.credit||null;previewCreditSummary=detail.creditSummary||null;}view='preview';render();return;}if(target.dataset.removeRow!==undefined){readForm();draft.lines.splice(Number(target.dataset.removeRow),1);dirty=true;render();return;}if(action==='new'){previewRecord=null;preview=null;previewCredit=null;previewCreditSummary=null;draft=freshDraft();const selected=new URLSearchParams(location.search).get('customer');if(selected)chooseCustomer(selected);view='edit';render();return;}if(action==='list'){if(dirty&&!confirm('Lämna det osparade utkastet? Spara utkast först för att behålla ändringarna.'))return;dirty=false;view='list';render();return;}if(action==='edit'){view='edit';render();return;}if(action==='add-row'){readForm();draft.lines.push(blankLine());dirty=true;render();return;}if(action==='edit-customer-register'){readForm();if(!draft.customerNumber)throw new Error('Välj en kund först.');if(isDemo)Demo.patch(s=>{s.invoiceDraft=copy(draft);});else if(isSupabase){busy=true;await saveSupabaseDraft();}else{if(!issueRequestId)issueRequestId=crypto.randomUUID();busy=true;const saved=await api('/customer-invoices/draft',{method:'PUT',body:{draft:copy(draft),requestId:issueRequestId}});privateDraftRecord=saved.savedDraft||null;sessionStorage.removeItem(LEGACY_PRIVATE_DRAFT_KEY);}dirty=false;location.href=url('./customers.html?customer='+encodeURIComponent(draft.customerNumber)+'&return=invoice');return;}if(action==='save-draft'){readForm();if(isDemo)Demo.patch(s=>{s.invoiceDraft=copy(draft);});else if(isSupabase){busy=true;await saveSupabaseDraft();}else{if(!issueRequestId)issueRequestId=crypto.randomUUID();busy=true;const saved=await api('/customer-invoices/draft',{method:'PUT',body:{draft:copy(draft),requestId:issueRequestId}});privateDraftRecord=saved.savedDraft||null;sessionStorage.removeItem(LEGACY_PRIVATE_DRAFT_KEY);}dirty=false;notify(isDemo?'Utkastet är sparat i den här webbläsaren. Det är inte bokfört.':'Utkastet är sparat i företagets privata databas. Det är inte bokfört.');return;}if(action==='open-draft-pdf'||action==='print-draft-pdf'){busy=true;await openPdf(await draftDocument(),action==='print-draft-pdf',{archived:false});return;}if(action==='open-pdf'||action==='print-pdf'){busy=true;await openPdf(preview,action==='print-pdf');return;}if(action==='credit-invoice'){if(isDemo)throw new Error('Kreditering av bokförd faktura testas i den skyddade företagsportalen.');if(!previewRecord?.id)throw new Error('Fakturan saknar ett giltigt internt id.');const maxOre=Number(previewCreditSummary?.creditableOre ?? previewRecord.totalOre ?? 0);creditDialog={maxOre,amountText:inputAmount(maxOre),reason:'Felaktig faktura',error:''};render();return;}if(target.hasAttribute('data-credit-cancel')){creditDialog=null;render();return;}}catch(error){notify(error.message);}finally{busy=false;restoreButtonStates();}});
document.addEventListener('keydown',event=>{const form=event.target.closest?.('#invoice-form');if(!form||event.key!=='Enter')return;if(event.target.tagName==='TEXTAREA')return;if(event.target.matches('button[type="submit"],input[type="submit"]'))return;event.preventDefault();});
document.addEventListener('submit',async event=>{if(event.target.id==='credit-invoice-form'){event.preventDefault();if(busy||!creditDialog||!previewRecord?.id)return;const values=Object.fromEntries(new FormData(event.target));try{const creditAmountOre=Money.parseOre(values.creditAmount,{allowNegative:false,label:'Kreditbelopp'}),maxOre=Number(creditDialog.maxOre||0),reason=String(values.reason||'').trim();if(creditAmountOre<=0||creditAmountOre>maxOre)throw new Error('Kreditbeloppet måste vara större än 0 och högst '+amount(maxOre)+'.');if(reason.length<5)throw new Error('Ange en tydlig orsak med minst 5 tecken.');busy=true;if(isSupabase){const originalId=previewRecord.id;await issueSupabaseCredit({originalInvoiceId:originalId,creditDate:today(),reason,creditAmountOre});creditDialog=null;view='preview';dirty=false;render();notify(previewCredit?.refundOutstandingOre>0?'Kreditfakturan är skapad i Supabase. '+amount(previewCredit.refundOutstandingOre)+' ska återbetalas till kunden och registreras först när bankutbetalningen är genomförd.':'Kreditfakturan är skapad i Supabase och kreditbeloppet är kvittat mot öppet fakturasaldo.');}else{const created=await api('/customer-invoices/'+encodeURIComponent(previewRecord.id)+'/credit',{method:'POST',body:{requestId:crypto.randomUUID(),creditDate:today(),reason,creditAmountOre}});privateInvoices=privateInvoices.filter(row=>row.id!==created.original.id&&row.id!==created.invoice.id);privateInvoices.unshift(created.invoice);privateInvoices.unshift(created.original);previewRecord=created.invoice;preview=created.document;previewCredit=created.credit||null;previewCreditSummary=null;creditDialog=null;view='preview';dirty=false;render();notify(previewCredit?.refundOutstandingOre>0?'Kreditfakturan är skapad. '+amount(previewCredit.refundOutstandingOre)+' ska återbetalas till kunden och registreras först när bankutbetalningen är genomförd.':'Kreditfakturan är skapad och kreditbeloppet är kvittat mot öppet fakturasaldo.');}}catch(error){creditDialog={...creditDialog,amountText:String(values.creditAmount||''),reason:String(values.reason||''),error:error.message};render();}finally{busy=false;restoreButtonStates();}return;}if(event.target.id!=='invoice-form')return;event.preventDefault();if(busy)return;try{readForm();const value=input();busy=true;for(const button of app.querySelectorAll('button'))button.disabled=true;const preflight=Invoice.prepare(value,{accounts:accounts(),requireVatTreatment:false});await Pdf.createInvoicePdf(preflight);if(isDemo){let created;Demo.patch(state=>{created=Invoice.postDemoInvoice(state,value);state.invoiceDraft=null;});previewRecord=created;preview=created.document;}else if(isSupabase){await issueSupabaseInvoice(value);}else{if(!issueReady)throw new Error(issueBlocker||'Företagets fakturauppgifter måste verifieras före bokföring.');if(!issueRequestId)issueRequestId=crypto.randomUUID();const payload={requestId:issueRequestId,customerNumber:value.customerNumber,invoiceDate:value.invoiceDate,postingDate:value.postingDate,dueDate:value.dueDate,paymentTermsDays:value.paymentTermsDays,ourReference:value.ourReference,yourReference:value.yourReference,notes:value.notes,lines:value.lines};const created=await api('/customer-invoices',{method:'POST',body:payload});previewRecord=created.invoice;preview=created.document;previewCredit=created.credit||null;previewCreditSummary=created.creditSummary||null;privateInvoices=privateInvoices.filter(row=>row.id!==created.invoice.id);privateInvoices.unshift(created.invoice);privateDraftRecord=null;sessionStorage.removeItem(LEGACY_PRIVATE_DRAFT_KEY);issueRequestId='';}view='preview';dirty=false;render();}catch(error){notify(error.message);}finally{busy=false;restoreButtonStates();}});
async function refreshPrivateCustomers(){if(isDemo)return;const editingForm=view==='edit'&&draft?.customerNumber&&document.getElementById('invoice-form');if(editingForm)readForm();const before=JSON.stringify(draft?.buyer||{});if(isSupabase){const ctx=await supabaseContext(),rows=await window.LTSupabase.from('customers',ctx.accessToken).select('*','company_id=eq.'+encodeURIComponent(ctx.company.id)+'&archived_at=is.null');privateCustomers=(rows||[]).map(r=>({id:r.id,customerNumber:r.customer_number,name:r.name,orgNumber:r.org_number||'',email:r.email||'',address:r.address_json||{},paymentTermsDays:30}));}else{const data=await api('/customers');privateCustomers=data.customers||[];}if(editingForm){syncDraftBuyer();if(JSON.stringify(draft.buyer||{})!==before)render();}}
addEventListener('focus',()=>{later(refreshAccounts);refreshPrivateCustomers().catch(()=>{});});addEventListener('storage',()=>later(refreshAccounts));addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
async function boot(){const resume=new URLSearchParams(location.search).get('resume')==='1';if(isDemo){const response=await fetch('../content/company.json');if(!response.ok)throw new Error('Företagsinställningarna kunde inte hämtas.');company=await response.json();if(resume){draft=freshDraft();view='edit';}render();return;}if(isSupabase){await refreshSupabaseCollections();if(resume){draft=freshDraft();view='edit';}render();return;}const sessionResponse=await fetch('/api/v1/session',{credentials:'same-origin',cache:'no-store'});const session=await sessionResponse.json();if(!session.authenticated){location.href='./index.html';return;}if(!csrfToken){location.href='./index.html';return;}const [customerData,invoiceData,configData,draftData]=await Promise.all([api('/customers'),api('/customer-invoices'),api('/customer-invoices/config'),api('/customer-invoices/draft')]);privateCustomers=customerData.customers||[];privateInvoices=invoiceData.invoices||[];company=configData.company||{};issueReady=configData.issuanceReady===true;issueBlocker=configData.blocker||'';privateDraftRecord=draftData.savedDraft||null;const legacy=readLegacyPrivateDraft();if(privateDraftRecord)sessionStorage.removeItem(LEGACY_PRIVATE_DRAFT_KEY);else if(legacy?.draft){try{const requestId=legacy.requestId||crypto.randomUUID(),saved=await api('/customer-invoices/draft',{method:'PUT',body:{draft:legacy.draft,requestId}});privateDraftRecord=saved.savedDraft||{draft:legacy.draft,requestId};sessionStorage.removeItem(LEGACY_PRIVATE_DRAFT_KEY);}catch{privateDraftRecord=legacy;}}if(resume){draft=freshDraft();view='edit';}render();}
boot().catch(error=>{app.innerHTML=`<div class="portal"><aside class="sidebar"></aside><main class="content"><h1>Fakturaverktyget kunde inte laddas</h1><p>${esc(error.message)}</p></main></div>`;});
